// NewTrainingsApi creates a new instance of TrainingsApi. It also registers a testing interface on the mock and a cleanup function to assert the mocks expectations.
// The first argument is typically a *testing.T value.
func NewTrainingsApi(t interface {
	mock.TestingT
	Cleanup(func())
}) *TrainingsApi {
	mock := &TrainingsApi{}
	mock.Mock.Test(t)

	t.Cleanup(func() { mock.AssertExpectations(t) })

	return mock
}
